package tests

import (
	bili "app-user/internal/bili/bili"

	"testing"
	"time"
)

// Fixtures generated by app/services/wbi.py — the two implementations must
// agree byte-for-byte. If this fails, fix Go, not the test.
func TestBiliMixinKey(t *testing.T) {
	orig := "7cd084941338484aae1ad9425b84077c4932cab080c8e8c8d3c4d48291c9e1c6"
	want := "c81d4124ac3cc082484393ca70404b08"
	if got := bili.MixinKey(orig); got != want {
		t.Fatalf("mixinKey = %q, want %q", got, want)
	}
}

func TestBiliSignParams(t *testing.T) {
	fixtureMixin := "c81d4124ac3cc082484393ca70404b08"
	params := map[string]string{
		"bvid": "BV1xx411c7mD",
		"cid":  "12345",
		"foo":  "va!l*ue",
	}
	now := time.Unix(1728000000, 0)
	signed := bili.SignParams(params, fixtureMixin, now)

	if got := signed.Get("wts"); got != "1728000000" {
		t.Fatalf("wts = %q", got)
	}
	// Characters !'()* are filtered before signing.
	if got := signed.Get("foo"); got != "value" {
		t.Fatalf("foo = %q, want filtered %q", got, "value")
	}
	if got := signed.Get("w_rid"); got != "4762c352007a52f1b0e2c77ded068679" {
		t.Fatalf("w_rid = %q", got)
	}
}

func TestBiliExtractWbiKeys(t *testing.T) {
	nav := map[string]any{
		"code": -101,
		"data": map[string]any{
			"wbi_img": map[string]any{
				"img_url": "https://i0.hdslb.com/bfs/wbi/7cd084941338484aae1ad9425b84077c.png",
				"sub_url": "https://i0.hdslb.com/bfs/wbi/4932cab080c8e8c8d3c4d48291c9e1c6.png",
			},
		},
	}
	img, sub, err := bili.ExtractWbiKeys(nav)
	if err != nil {
		t.Fatal(err)
	}
	if img != "7cd084941338484aae1ad9425b84077c" || sub != "4932cab080c8e8c8d3c4d48291c9e1c6" {
		t.Fatalf("keys = %q / %q", img, sub)
	}
}

func TestBiliBVToAV(t *testing.T) {
	cases := map[string]int64{
		"BV1GJ411x7h7": 80433022,
		"BV1xx411c7mD": 2,
		"BV1Av411q7re": 243875718,
	}
	for bvid, want := range cases {
		if got := bili.BVToAV(bvid); got != want {
			t.Errorf("bili.BVToAV(%s) = %d, want %d", bvid, got, want)
		}
	}
	if bili.BVToAV("BV") != 0 {
		t.Fatal("malformed bvid must yield 0")
	}
}
